"""Write docs/RESULTS.md: every results/*.json table as Markdown (generated, do not edit).
`--check` fails when the file is out of date (CI keeps the dossier's numbers honest)."""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

import yaml

ROOT = Path(__file__).resolve().parents[1]
RES = ROOT / "results"


def j(n):
    return json.loads((RES / f"{n}.json").read_text(encoding="utf-8"))


def f(x, d=2):
    if x is None:
        return "n/a"
    if x == "inf":
        return "> run"
    if isinstance(x, bool):
        return "yes" if x else "**no**"
    if isinstance(x, (int, float)):
        return f"{x:.{d}f}"
    return str(x)


def render() -> str:
    L = ["# Results (generated)", "",
         "Generated by `python tools/results_md.py` from `results/*.json` (written by `python -m swpower all`). Do not edit.", ""]
    b = j("budget")
    L += ["## R1. Power budget (W at 28 V)", "", "| Mode | CBE | + growth allowance | allocated (+10 % system margin) | coincident peak |",
          "|---|---|---|---|---|"]
    for m, v in b["modes"].items():
        L.append(f"| {m} | {v['cbe_w']:.0f} | {v['with_growth_w']:.0f} | {v['allocated_w']:.0f} | {v['coincident_peak_w']:.0f} |")
    L += ["", "| Load | Priority | SSPC ch. | Basis | Silent-watch avg W | peak W | Sources |", "|---|---|---|---|---|---|---|"]
    for r in b["loads"]:
        L.append(f"| {r['id']}: {r['name']} | P{r['priority']} | {r['channel']} | {r['basis']} | {r['sw_avg_w']:.0f} | "
                 f"{r['sw_peak_w']:.0f} | {', '.join(r['src']) or '-'} |")
    L += ["", f"Equipment heat into the compartment (silent watch, with growth): **{b['equipment_heat_w']:.0f} W**.", "",
          "## R2. Thermal budget", "", "| Climate | T_amb degC | solar W/m2 | uncooled degC | cooling needed W | ECU draw W | h to 40 degC from 35 without cooling |",
          "|---|---|---|---|---|---|---|"]
    for k, v in b["thermal"].items():
        L.append(f"| {k} | {v['t_amb']:.0f} | {v['g_solar']:.0f} | {v['t_uncooled']:.0f} | {v['q_cool_w']:.0f} | {v['ecu_w']:.0f} | "
                 f"{f(v['hours_to_limit_no_cooling'])} |")
    v = j("battery_validation")
    L += ["", "## R3. Battery model credibility", "", "| Specification test | Model | Required | Pass |", "|---|---|---|---|"]
    for r in v["spec"]:
        L.append(f"| {r['test']} | {r['model']} | {r['required']} | {f(r['pass'])} |")
    L += ["", "| Current per block A | Product data sheet min | Model min | Ratio |", "|---|---|---|---|"]
    for r in v["product"]:
        L.append(f"| {r['current_a']:.1f} | {r['product_min']:.0f} | {r['model_min']:.1f} | {r['ratio']:.2f} |")
    rs = j("reserve")
    L += ["", "## R4. Engine-start reserve SOC (3 x 10 s at 600 A, bus >= 16 V); n/a = cannot start when full", "",
          "| Bank | 25 degC | 0 | -18 | -32 | -46 |", "|---|---|---|---|---|---|"]
    for k, d in rs.items():
        L.append(f"| {k} | " + " | ".join(f(d[t]) for t in ("25.0", "0.0", "-18.0", "-32.0", "-46.0")) + " |")
    s = j("sizing")
    L += ["", "## R5. Sizing: hours of silent watch (engine and APU off) vs mission-bank size", "",
          "Cell = full suite / essential P1-P2 / vital P1 hours; `> run` = still running at the end of the 20 h run; crank = engine start after the watch.", ""]
    for arch, d in s.items():
        nps = [r["np"] for r in next(iter(d.values()))]
        unit = "strings of 2 blocks" if "agm" in arch else "blocks"
        L += [f"**{arch}** (np = {unit})", "", "| Climate | " + " | ".join(f"np {n}" for n in nps) + " |",
              "|---|" + "---|" * len(nps)]
        for cl, rows in d.items():
            L.append(f"| {cl} | " + " | ".join(f"{f(r['full_h'], 1)} / {f(r['essential_h'], 1)} / {f(r['vital_h'], 1)}"
                                                + ("" if r["crank_ok"] else " (crank **fail**)") for r in rows) + " |")
        L.append("")
    a = j("aoa")
    crit = a["criteria"]
    L += ["## R6. Analysis of alternatives", "", "| Alt | Description | " + " | ".join(c["id"] for c in crit) + " | cold crank | FOM |",
          "|---|---|" + "---|" * (len(crit) + 2)]
    for k, e in a["alternatives"].items():
        fom = a["score"]["fom"].get(k)
        so = a["score"]["screened_out"].get(k)
        L.append(f"| {k} | {e['label']} | " + " | ".join(f(e['values'][c['id']]) for c in crit) +
                 f" | {f(e['crank_after_cold_watch'])} | {f(fom, 3) if fom is not None else 'out: ' + ', '.join(so)} |")
    L += ["", "Weights (auto-normalised): " + ", ".join(f"{c['id']} {w:.3f}" for c, w in zip(crit, a["weights"])), "",
          "Sensitivity (each weight -10 %, renormalised): " +
          ", ".join(f"{x['criterion']} -> {x['winner']}" for x in a["sensitivity"]), "",
          f"Random weights (each rating x U(0.5, 1.5), 2000 draws), share ranked first: {a['mc_weights']}", ""]
    t = j("transients")
    L += ["## R7. MIL-STD-1275E front end", "", "| Front end | Case | TVS J | FET J | Tj peak degC | input max V | DC/DC min V | DC/DC max V | dropouts | pass |",
          "|---|---|---|---|---|---|---|---|---|---|"]
    for fe, d in t.items():
        for c, r in d.items():
            bad = [k for k, ok in r["checks"].items() if not ok]
            L.append(f"| {fe} | {c} | {r['e_tvs_j']:.2f} | {r['e_fet_j']:.2f} | {r['tj_peak_c']:.0f} | {r['va_max']:.0f} | {r['vb_min']:.1f} | "
                     f"{r['vb_max']:.1f} | {r['dropouts']} | {'yes' if r['pass'] else '**no** (' + ', '.join(bad) + ')'} |")
    sp = j("sspc")
    L += ["", "## R8. SSPC channels and wire coordination", "", "| Ch | Loads | Prio | Peak W | I at 20 V | Rating A | Wire mm2 | min damage/trip time |",
          "|---|---|---|---|---|---|---|---|"]
    for r in sp["channels"]:
        L.append(f"| {r['channel']} | {', '.join(r['loads'])} | P{r['priority']} | {r['peak_w']:.0f} | {r['i_peak_a']:.1f} | {r['rating_a']:g} | "
                 f"{r['wire_mm2']:g} | {r['min_damage_to_trip']:.2f} |")
    L += ["", f"Fault coverage on a 10 A channel with {sp['rep_wire_mm2']:g} mm2 wire: **{sp['coverage']}**", "",
          "| Fault | Trip s | Wire damage s | Covered | How |", "|---|---|---|---|---|"]
    for x in sp["fault_cases"]:
        L.append(f"| {x['id']} {x['name']} | {f(x['trip_s'], 4)} | {f(x['damage_s'], 1)} | {f(x['covered'])} | {x['how']} |")
    r = j("rma")
    L += ["", f"## R9. Reliability and availability ({r['alternative']})", "", "| Case | R(4 h) | R(12 h) |", "|---|---|---|"]
    for k, d in r["rbd"].items():
        L.append(f"| {k} | {d['R_4h']:.4f} | {d['R_12h']:.4f} |")
    av = r["availability"]
    L += ["", f"MTBF {av['mtbf_h']:.0f} h, MCMT {av['mcmt_h']:.2f} h, A_i {av['A_i']:.4f}, MDT {av['mdt_h']:.1f} h, A_o {av['A_o']:.4f}.",
          f"Failure-rate sensitivity of R(12 h): {r['rate_sensitivity_R12']}", ""]
    m = j("monte_carlo")
    L += ["## R10. Monte Carlo of the uncertain inputs", "",
          f"{m['alternative']} at {m['climate']}, {m['n']} runs: essential-suite hours mean {m['mean_h']:.2f}, P5 {m['p05_h']:.2f}, "
          f"median {m['p50_h']:.2f}, P95 {m['p95_h']:.2f}; P(>= 4 h) = **{m['p_meets_threshold']:.2f}**.", ""]
    d = j("decision")
    L += ["## R12. 4 h or 12 h: silent hours by crew posture (engine and APU off; `> 24` = still on after 24 h)", "",
          "| Posture | Li-ion blocks | " + " | ".join(f"{tag} {t:+.0f} degC" for tag, t, g in d["conditions"]) + " |",
          "|---|---|" + "---|" * len(d["conditions"])]
    for r in d["rows"]:
        L.append(f"| {r['posture']} | {r['blocks']} | " + " | ".join("> 24" if h >= 24 else f"{h:.1f}" for h in r["hours"]) + " |")
    c = j("conflict")
    L += ["", "## R13. Cranking-voltage conflict: lowest bank voltage, full spec-minimum bank (1275 floor 16 V; 32565C allows 14.4 V)", "",
          "| Start bank | " + " | ".join(c["cases"]) + " |", "|---|" + "---|" * len(c["cases"])]
    for r in c["rows"]:
        L.append(f"| {r['bank']} | " + " | ".join(f"{r[k]:.1f}" for k in c["cases"]) + " |")
    a = j("arc")
    L += ["", f"## R14. Arc-fault detector on held-out seeds (seed {a['seed']}, {a['n_each']} per class)", "",
          "| Class | n | tripped | median ms | max ms |", "|---|---|---|---|---|"]
    for k, v in a["classes"].items():
        L.append(f"| {k} | {v['n']} | {v['tripped']} | {f(v['median_ms'], 0)} | {f(v['max_ms'], 0)} |")
    L.append("")
    fm = yaml.safe_load((ROOT / "data" / "fmea.yaml").read_text(encoding="utf-8"))["rows"]
    L += ["## R11. FMEA (data/fmea.yaml)", "", "| ID | Item | Failure mode | End effect | Detection | Compensating provision | Sev | Prob | Verified by |",
          "|---|---|---|---|---|---|---|---|---|"]
    for x in fm:
        L.append(f"| {x['id']} | {x['item']} | {x['mode']} | {x['end']} | {x['detect']} | {x['provision']} | {x['sev']} | {x['prob']} | "
                 f"{', '.join(x['verify'])} |")
    L.append("")
    return "\n".join(L)


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--check", action="store_true")
    a = ap.parse_args()
    text = render()
    p = ROOT / "docs" / "RESULTS.md"
    if a.check:
        ok = p.exists() and p.read_text(encoding="utf-8") == text
        print("docs/RESULTS.md is current" if ok else "docs/RESULTS.md is out of date")
        return 0 if ok else 1
    p.write_text(text, encoding="utf-8", newline="\n")
    print("wrote", p.relative_to(ROOT))
    return 0


if __name__ == "__main__":
    sys.exit(main())
